@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<BlogListingBlock>>
@{
    var posts = Umbraco.AssignedContentItem.Children<BlogPostPage>()
        .OrderByDescending(post => post.CreateDate)
        .Select(post => new BlogPostCard(post.Name, post.Url(), post.Excerpt ?? ""))
        .ToList();
    var model = new BlogListingModel
    {
        Heading = Model.Content.Heading ?? "",
        Intro = Model.Content.Intro ?? "",
        Posts = posts
    };
}
@await Component.InvokeAsync("BlogListing", new { model })

@model Umbraco.Bench.Umbraco.Models.Blocks.HeroModel

<section class="relative isolate overflow-hidden bg-slate-950 text-white">
    @if (!string.IsNullOrWhiteSpace(Model.ImageUrl))
    {
        <img src="@Model.ImageUrl" alt="" class="absolute inset-0 -z-10 h-full w-full object-cover opacity-35" />
    }
    <div class="mx-auto max-w-6xl px-6 py-24 sm:py-32">
        <p class="mb-5 text-sm font-semibold uppercase tracking-[0.25em] text-cyan-300">MCP Journal</p>
        <h1 class="max-w-4xl text-4xl font-bold tracking-tight sm:text-6xl">@Model.Heading</h1>
        <p class="mt-6 max-w-2xl text-lg leading-8 text-slate-200">@Model.Intro</p>
    </div>
</section>

